import { forwardRef, type ButtonHTMLAttributes } from "react";

type ButtonVariant = "default" | "outline" | "ghost" | "danger";
type ButtonSize = "sm" | "md" | "lg" | "icon";
export type ButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & { variant?: ButtonVariant; size?: ButtonSize };

const base = "co-inline-flex co-items-center co-justify-center co-gap-2 co-rounded-md co-font-medium co-transition co-outline-none focus-visible:co-ring-2 focus-visible:co-ring-black disabled:co-pointer-events-none disabled:co-opacity-50";
const variants: Record<ButtonVariant, string> = {
  default: "co-bg-black co-text-white hover:co-bg-black/80",
  outline: "co-border co-border-black/20 co-bg-white co-text-black hover:co-bg-black/5",
  ghost: "co-bg-transparent co-text-black hover:co-bg-black/5",
  danger: "co-bg-black co-text-white hover:co-opacity-80",
};
const sizes: Record<ButtonSize, string> = { sm: "co-h-8 co-px-3 co-text-xs", md: "co-h-10 co-px-4 co-text-sm", lg: "co-h-12 co-px-6", icon: "co-size-10" };

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(({ className = "", variant = "default", size = "md", type = "button", ...props }, ref) => (
  <button ref={ref} type={type} className={`${base} ${variants[variant]} ${sizes[size]} ${className}`.trim()} {...props} />
));
Button.displayName = "Button";
